  insert into public.catalog_domain (version_id, code, name, control_count, display_order) values
    (v_version, 'GOV', 'Gouvernance', 12, 1),
    (v_version, 'INV', 'Inventaire des systèmes d''IA', 8, 2),
    (v_version, 'USE', 'Gestion des cas d''usage', 10, 3),
    (v_version, 'RSK', 'Gestion des risques IA', 12, 4),
    (v_version, 'DAT', 'Gouvernance des données', 12, 5),
    (v_version, 'SEC', 'Sécurité de l''IA', 12, 6),
    (v_version, 'SUP', 'Fournisseurs et modèles', 10, 7),
