         c.assessment_questions, c.expected_evidence, c.tests, c.maturity_model,
         c.framework_mappings, c.remediation_guidance
  from jsonb_to_recordset($controls$[{"code":"AIGMS-GOV-001","version":"0.3","title":"Politique de gouvernance de l'IA","status":"draft","control_type":"baseline","objective":"Une politique approuvée par la direction fixe ce que l'organisation attend de l'IA : finalités permises, usages interdits, principes (transparence, supervision humaine, protection des données), et qui décide de quoi.","owner_role":"Direction","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La politique est-elle approuvée par la direction et datée ?","Nomme-t-elle les usages interdits et les usages soumis à autorisation ?","Est-elle communiquée aux personnes concernées et retrouvable ?"],"expected_evidence":["Politique d'IA signée et versionnée","Preuve de diffusion (intranet, accusé de lecture)","Compte rendu de l'approbation en revue de direction"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.2.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.2.3"},{"framework":"AI_ACT","reference":"Art. 4 (maîtrise de l'IA)"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-002","version":"0.3","title":"Périmètre du système de management de l'IA","status":"draft","control_type":"baseline","objective":"Le périmètre du système de management est écrit : entités, processus, sites, systèmes d'IA couverts, et ce qui en est exclu avec sa justification. Sans périmètre, aucune déclaration d'applicabilité ne tient.","owner_role":"AI Governance Officer","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le périmètre nomme-t-il les entités, processus et systèmes couverts ?","Les exclusions sont-elles justifiées ?","Le rôle de l'organisation vis-à-vis de l'IA (fournisseur, développeur, intégrateur, utilisateur) est-il déclaré ?"],"expected_evidence":["Document de périmètre du SMIA","Déclaration du rôle vis-à-vis de l'IA","Liste des exclusions justifiées"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.2.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.2"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-003","version":"0.3","title":"Rôles et responsabilités","status":"draft","control_type":"baseline","objective":"Chaque responsabilité de la gouvernance de l'IA — décider, évaluer, superviser, répondre — est attribuée à un rôle nommé, avec une personne identifiée, et les séparations nécessaires (celui qui demande n'est pas celui qui approuve) sont posées.","owner_role":"Direction","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Existe-t-il une matrice des responsabilités (RACI ou équivalent) pour l'IA ?","Chaque rôle est-il porté par une personne nommée, avec suppléance ?","La séparation demandeur / approbateur est-elle effective sur les décisions engageantes ?"],"expected_evidence":["Matrice des responsabilités IA","Fiches de rôle ou lettres de mission","Extrait du registre de décisions montrant la séparation des rôles"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.3.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.2"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-004","version":"0.3","title":"Comité de gouvernance de l'IA","status":"draft","control_type":"baseline","objective":"Une instance se réunit à cadence fixe pour arbitrer : autorisations, acceptations de risque, exceptions, revue des incidents et du portefeuille. Ses décisions sont consignées.","owner_role":"AI Governance Officer","review_frequency":"quarterly","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Le comité a-t-il un mandat écrit, une composition et une cadence ?","Ses décisions sont-elles consignées dans le registre de décisions ?","Les sujets obligatoires (incidents, risques acceptés, exceptions) y passent-ils ?"],"expected_evidence":["Mandat du comité","Comptes rendus datés","Registre de décisions"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.3.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"9.3"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-005","version":"0.3","title":"Propriétaire du système d'IA","status":"draft","control_type":"baseline","objective":"Chaque système d'IA a un propriétaire opérationnel nommé, responsable de son fonctionnement, de sa documentation et des preuves qu'il doit produire — distinct du responsable redevable.","owner_role":"AI Governance Officer","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Chaque usage inscrit au registre a-t-il un propriétaire nommé ?","Le propriétaire connaît-il ses obligations (preuves, revues, incidents) ?","Un changement de propriétaire est-il tracé ?"],"expected_evidence":["Registre des usages avec propriétaire","Fiche de responsabilités du propriétaire","Journal des changements de propriétaire"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.3.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.2"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-006","version":"0.3","title":"Responsable du risque","status":"draft","control_type":"baseline","objective":"Un responsable du risque nommé cote les risques liés à l'IA, décide de leur traitement et porte les acceptations. Il n'est pas le propriétaire du système qu'il évalue.","owner_role":"Responsable du risque","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le responsable du risque est-il nommé et distinct du propriétaire du système ?","Les acceptations de risque portent-elles sa signature, une justification et une date de revue ?"],"expected_evidence":["Nomination du responsable du risque","Registre des risques avec acceptations signées"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.3.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-007","version":"0.3","title":"Responsable des données","status":"draft","control_type":"baseline","objective":"Un responsable des données est nommé pour chaque jeu de données mobilisé par l'IA — provenance, qualité, base légale, conservation — et répond de leur usage.","owner_role":"Responsable des données","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Chaque jeu de données d'entraînement ou d'exploitation a-t-il un responsable nommé ?","Le responsable des données est-il consulté lors de l'évaluation d'impact ?"],"expected_evidence":["Inventaire des jeux de données avec responsable","Trace de consultation dans les évaluations d'impact"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.2"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-008","version":"0.3","title":"Politique d'usage acceptable de l'IA","status":"draft","control_type":"baseline","objective":"Les collaborateurs savent ce qu'ils peuvent faire avec les outils d'IA — internes ou grand public — et ce qu'ils ne peuvent pas : données à ne pas soumettre, usages interdits, obligation de déclarer un nouvel usage.","owner_role":"AI Governance Officer","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La politique d'usage est-elle diffusée à tous les collaborateurs ?","Interdit-elle explicitement la soumission de données confidentielles ou personnelles à des outils non approuvés ?","Le signalement d'un usage non déclaré (IA de l'ombre) est-il organisé ?"],"expected_evidence":["Politique d'usage acceptable","Attestations de prise de connaissance","Canal de signalement documenté"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.2.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"},{"framework":"AI_ACT","reference":"Art. 4 (maîtrise de l'IA)"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-009","version":"0.3","title":"Processus d'approbation des usages d'IA","status":"draft","control_type":"baseline","objective":"Aucun usage d'IA n'entre en service sans passer les jalons prévus — déclaration, qualification, revue, décision de mise en production — chacun avec ses préconditions vérifiées et sa décision consignée.","owner_role":"AI Governance Officer","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le cycle de vie et ses jalons sont-ils définis et appliqués ?","Les préconditions de chaque jalon sont-elles vérifiées, et les refus tracés ?","Une décision de mise en production porte-t-elle un approbateur distinct du demandeur ?"],"expected_evidence":["Procédure du cycle de vie","Journal des gates évalués et refusés","Registre de décisions"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.5"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-010","version":"0.3","title":"Gestion des exceptions","status":"draft","control_type":"baseline","objective":"Une dérogation à la politique se demande, se justifie, s'approuve par un rôle habilité, porte une date de fin et une revue. Une exception non tracée est une politique qui n'existe plus.","owner_role":"AI Governance Officer","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les exceptions sont-elles enregistrées avec leur justification, leur approbateur et leur échéance ?","Sont-elles revues à échéance, et closes ou renouvelées explicitement ?"],"expected_evidence":["Registre de décisions filtré sur les exceptions","Revues d'échéance"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.2.4"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-011","version":"0.3","title":"Revue de direction de l'IA","status":"draft","control_type":"baseline","objective":"La direction revoit périodiquement le système de management : état du portefeuille, incidents, risques acceptés, résultats d'audit, ressources, et décide des orientations.","owner_role":"Direction","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La revue de direction a-t-elle lieu à la cadence prévue, avec les entrées requises ?","Ses conclusions produisent-elles des décisions et des actions suivies ?"],"expected_evidence":["Dossier d'entrée de la revue","Compte rendu et décisions","Actions issues de la revue, suivies"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"9.3"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-GOV-012","version":"0.3","title":"Amélioration continue","status":"draft","control_type":"baseline","objective":"Les non-conformités, incidents, constats d'audit et retours d'expérience alimentent des actions correctives dont l'efficacité est vérifiée, et le système de management évolue en conséquence.","owner_role":"AI Governance Officer","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les actions correctives portent-elles une analyse de cause et une vérification d'efficacité ?","Les enseignements sont-ils réinjectés dans la politique, les contrôles ou la formation ?"],"expected_evidence":["Registre des actions correctives (CAPA) avec vérification d'efficacité","Historique des versions de la politique et des procédures"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.2.4"}],"remediation_guidance":[],"domain":"GOV"},{"code":"AIGMS-INV-001","version":"0.3","title":"Inventaire central des systèmes d'IA","status":"draft","control_type":"baseline","objective":"Tous les systèmes d'IA utilisés, développés ou fournis par l'organisation — y compris les fonctions d'IA embarquées dans des outils tiers — sont inscrits dans un registre unique, tenu à jour.","owner_role":"AI Governance Officer","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Existe-t-il un registre unique des systèmes et usages d'IA ?","Une démarche de détection des usages non déclarés est-elle en place (revue des achats, des connecteurs, des journaux) ?","Le registre est-il revu à cadence fixe ?"],"expected_evidence":["Registre des usages d'IA exporté et daté","Rapport de détection des usages non déclarés","Revue périodique du registre"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.7"},{"framework":"AI_ACT","reference":"Art. 49 (enregistrement)"}],"remediation_guidance":[],"domain":"INV"},{"code":"AIGMS-INV-002","version":"0.3","title":"Identification du propriétaire","status":"draft","control_type":"baseline","objective":"Chaque entrée du registre nomme son propriétaire opérationnel et son responsable redevable. Une entrée sans propriétaire n'est pas gouvernée.","owner_role":"AI Governance Officer","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Aucune entrée du registre n'est-elle sans propriétaire ni redevable ?"],"expected_evidence":["Registre des usages : colonnes propriétaire et redevable renseignées"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.3.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.2"}],"remediation_guidance":[],"domain":"INV"},{"code":"AIGMS-INV-003","version":"0.3","title":"Description de la finalité","status":"draft","control_type":"baseline","objective":"Chaque système d'IA porte une finalité écrite, lisible hors contexte : à quoi il sert, ce qu'il produit, ce qu'il ne fait pas. C'est la référence pour juger de tout changement ultérieur.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La finalité est-elle décrite en termes compréhensibles par un non-spécialiste ?","Distingue-t-elle l'usage prévu des usages exclus ?"],"expected_evidence":["Fiche du cas d'usage : finalité et usage prévu"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.4"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.2"}],"remediation_guidance":[],"domain":"INV"},{"code":"AIGMS-INV-004","version":"0.3","title":"Identification des utilisateurs","status":"draft","control_type":"baseline","objective":"Les utilisateurs du système — internes, clients, partenaires — sont identifiés par catégorie, avec leur niveau de compétence attendu et l'information qui leur est due.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les catégories d'utilisateurs sont-elles décrites ?","Les utilisateurs savent-ils qu'ils interagissent avec une IA ?"],"expected_evidence":["Fiche du cas d'usage : utilisateurs","Notice ou mention d'information aux utilisateurs"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.8.2"},{"framework":"AI_ACT","reference":"Art. 50 (transparence)"}],"remediation_guidance":[],"domain":"INV"},{"code":"AIGMS-INV-005","version":"0.3","title":"Identification des populations affectées","status":"draft","control_type":"baseline","objective":"Les personnes et groupes affectés par le système sans en être les utilisateurs — candidats, clients évalués, salariés notés — sont identifiés, avec une attention particulière aux personnes vulnérables.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les personnes affectées sont-elles distinguées des utilisateurs ?","Les personnes vulnérables sont-elles identifiées, et l'évaluation d'impact en tient-elle compte ?"],"expected_evidence":["Fiche du cas d'usage : personnes concernées","Évaluation d'impact : parties affectées"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.4"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.8.5"}],"remediation_guidance":[],"domain":"INV"},{"code":"AIGMS-INV-006","version":"0.3","title":"Modèle, fournisseur et version","status":"draft","control_type":"baseline","objective":"Le modèle utilisé, son éditeur, sa version et son mode d'hébergement sont inscrits pour chaque système. Un changement de modèle est un changement à qualifier.","owner_role":"Porteur du système","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le modèle et sa version sont-ils connus pour chaque système en service ?","Un changement de version déclenche-t-il une demande de changement ?"],"expected_evidence":["Registre des actifs : modèles et versions","Demandes de changement liées aux montées de version"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.4"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"}],"remediation_guidance":[],"domain":"INV"},{"code":"AIGMS-INV-007","version":"0.3","title":"Interfaces et dépendances","status":"draft","control_type":"baseline","objective":"Les systèmes, données et services dont dépend chaque système d'IA — et ceux qui dépendent de lui — sont cartographiés, pour mesurer la portée d'une panne, d'une dérive ou d'un changement.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Les dépendances entrantes et sortantes sont-elles documentées ?","La cartographie est-elle utilisée dans l'analyse d'impact des changements ?"],"expected_evidence":["Schéma ou liste des dépendances","Analyse d'impact d'un changement s'y référant"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.5"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.7"}],"remediation_guidance":[],"domain":"INV"},{"code":"AIGMS-INV-008","version":"0.3","title":"Statut du cycle de vie","status":"draft","control_type":"baseline","objective":"Chaque système porte un statut de cycle de vie à jour — de la déclaration au retrait — et ne change de statut que par les jalons prévus. Un système retiré reste au registre.","owner_role":"AI Governance Officer","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le statut de chaque système correspond-il à la réalité opérationnelle ?","Les changements de statut sont-ils tracés avec leur motif ?"],"expected_evidence":["Registre des usages : statuts","Journal des transitions"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.5"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"}],"remediation_guidance":[],"domain":"INV"},{"code":"AIGMS-USE-001","version":"0.3","title":"Description du cas d'usage","status":"draft","control_type":"baseline","objective":"Chaque cas d'usage est décrit avant toute mise en œuvre : contexte, processus métier servi, fonctionnement attendu, périmètre. C'est le point d'entrée de toute la gouvernance.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le cas d'usage est-il rattaché à un processus et une activité de l'organisation ?","La description permet-elle à un tiers de comprendre ce qui est fait et pourquoi ?"],"expected_evidence":["Fiche du cas d'usage complète","Rattachement à la cartographie des processus"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.4"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-002","version":"0.3","title":"Objectif métier","status":"draft","control_type":"baseline","objective":"L'objectif métier du cas d'usage est explicite et mesurable : quel problème il résout, pour qui, avec quel indicateur de succès.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["L'objectif est-il formulé en termes métier, avec un indicateur ?"],"expected_evidence":["Fiche du cas d'usage : objectif et indicateur"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.1.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.3"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-003","version":"0.3","title":"Valeur attendue","status":"draft","control_type":"baseline","objective":"Le bénéfice attendu est estimé — temps, coût, qualité, risque évité — et confronté au coût et au risque de l'usage. C'est ce qui justifie l'effort de gouvernance qu'on lui consacre.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Le bénéfice attendu est-il chiffré ou qualifié ?","Est-il revu une fois l'usage en service ?"],"expected_evidence":["Fiche du cas d'usage : bénéfice attendu","Bilan de valeur après mise en service"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.3"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-004","version":"0.3","title":"Parties prenantes","status":"draft","control_type":"baseline","objective":"Les parties prenantes du cas d'usage — métier, juridique, sécurité, données, représentants du personnel, clients — sont identifiées et consultées quand la décision l'exige.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les parties prenantes sont-elles listées ?","Leur consultation est-elle tracée dans l'évaluation d'impact ?"],"expected_evidence":["Évaluation d'impact : parties prenantes consultées"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.8.5"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.3"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-005","version":"0.3","title":"Utilisateurs","status":"draft","control_type":"baseline","objective":"Les utilisateurs du cas d'usage sont identifiés, formés à ce que le système fait et ne fait pas, et savent comment signaler un résultat douteux.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les utilisateurs ont-ils reçu une information ou une formation adaptée ?","Disposent-ils d'un canal de signalement ?"],"expected_evidence":["Support de formation ou notice utilisateur","Attestations de formation","Canal de signalement"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.6"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.8.2"},{"framework":"AI_ACT","reference":"Art. 4 (maîtrise de l'IA)"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-006","version":"0.3","title":"Décisions influencées","status":"draft","control_type":"baseline","objective":"Les décisions que le système prend, propose ou influence sont nommées, avec leur portée sur les personnes : information, recommandation, décision automatique. C'est ce qui détermine le niveau de supervision.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La portée des décisions est-elle décrite (informative, recommandation, automatique) ?","Une décision automatique sur une personne est-elle identifiée comme telle ?"],"expected_evidence":["Fiche du cas d'usage : portée des décisions","Classification réglementaire"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.4"},{"framework":"AI_ACT","reference":"Art. 6 et Annexe III (haut risque)"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-007","version":"0.3","title":"Niveau d'autonomie","status":"draft","control_type":"baseline","objective":"Le niveau d'autonomie du système est qualifié sur une échelle fixe (L0 assistance à L4 autonome), et toute montée d'autonomie est un changement qui rouvre l'évaluation et la supervision humaine.","owner_role":"AI Governance Officer","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le niveau d'autonomie est-il qualifié selon l'échelle de l'organisation ?","Au-delà de L2, une autorité d'arrêt nommée existe-t-elle ?"],"expected_evidence":["Fiche du cas d'usage : niveau d'autonomie","Plan de supervision humaine"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"},{"framework":"AI_ACT","reference":"Art. 14 (contrôle humain)"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-008","version":"0.3","title":"Impact potentiel","status":"draft","control_type":"baseline","objective":"L'impact potentiel du cas d'usage sur les personnes, l'organisation et la société est évalué avant la mise en service, et réévalué à chaque changement significatif.","owner_role":"AI Governance Officer","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Une évaluation d'impact existe-t-elle pour chaque usage en service ?","Est-elle rouverte à chaque changement significatif ?"],"expected_evidence":["Évaluation d'impact datée et approuvée","Réévaluations liées aux changements"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"8.4"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-009","version":"0.3","title":"Criticité","status":"draft","control_type":"baseline","objective":"Chaque cas d'usage reçoit une criticité (faible à critique) justifiée, qui commande la profondeur de l'évaluation, le niveau de preuve exigé et la cadence de revue.","owner_role":"AI Governance Officer","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La criticité est-elle attribuée avec une justification écrite ?","La cadence de revue suit-elle la criticité ?"],"expected_evidence":["Fiche du cas d'usage : criticité et justification","Date de prochaine revue"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.2"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-USE-010","version":"0.3","title":"Décision de mise en production","status":"draft","control_type":"baseline","objective":"La mise en production est une décision nominative, prise par un rôle habilité distinct du demandeur, une fois les préconditions satisfaites — risques traités, contrôles opérants, supervision décrite, revue tiers close.","owner_role":"AI Governance Officer","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Chaque usage en service a-t-il une décision de mise en production approuvée ?","L'approbateur est-il distinct du demandeur ?","Les préconditions du gate étaient-elles satisfaites au moment de la décision ?"],"expected_evidence":["Registre de décisions : décisions de mise en production","Journal du gate PRODUCTION"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.5"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.4"}],"remediation_guidance":[],"domain":"USE"},{"code":"AIGMS-RSK-001","version":"0.3","title":"Méthodologie de gestion des risques IA","status":"draft","control_type":"baseline","objective":"Une méthode écrite fixe comment les risques liés à l'IA sont identifiés, cotés, traités et acceptés : échelles, seuils, rôles, cadence. Elle s'articule avec la gestion des risques de l'organisation.","owner_role":"Responsable du risque","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La méthode est-elle écrite, approuvée et appliquée ?","Ses échelles sont-elles celles utilisées dans le registre des risques ?"],"expected_evidence":["Méthodologie de gestion des risques IA","Registre des risques conforme aux échelles"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-002","version":"0.3","title":"Identification des risques","status":"draft","control_type":"baseline","objective":"Pour chaque cas d'usage, les risques sont identifiés selon une grille couvrant au moins : erreur et hallucination, biais et discrimination, fuite de données, dépendance fournisseur, sécurité, usage détourné, impact sur les personnes.","owner_role":"Responsable du risque","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Chaque usage en service a-t-il au moins un risque identifié par catégorie pertinente ?","Les risques sont-ils rattachés à leur cas d'usage ?"],"expected_evidence":["Registre des risques par cas d'usage","Grille de catégories utilisée"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"},{"framework":"AI_ACT","reference":"Art. 9 (système de gestion des risques)"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-003","version":"0.3","title":"Évaluation de la probabilité","status":"draft","control_type":"baseline","objective":"La probabilité de chaque risque est cotée sur l'échelle de la méthode, avec les éléments qui la fondent — fréquence observée, retours d'expérience, résultats de tests.","owner_role":"Responsable du risque","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La probabilité est-elle cotée pour chaque risque, avec une justification ?"],"expected_evidence":["Registre des risques : probabilité et justification"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-004","version":"0.3","title":"Évaluation de l'impact","status":"draft","control_type":"baseline","objective":"L'impact de chaque risque est coté sur les personnes, l'organisation et la société — pas seulement en termes financiers — avec une attention particulière aux droits fondamentaux et aux personnes vulnérables.","owner_role":"Responsable du risque","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["L'impact est-il coté sur plusieurs dimensions (personnes, organisation, société) ?","Les impacts sur les personnes s'appuient-ils sur l'évaluation d'impact ?"],"expected_evidence":["Registre des risques : impact par dimension","Évaluation d'impact"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.4"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-005","version":"0.3","title":"Calcul du niveau de risque","status":"draft","control_type":"baseline","objective":"Le niveau de risque inhérent puis résiduel est déduit de la probabilité et de l'impact par la règle de la méthode — jamais ajusté à la main pour passer sous un seuil.","owner_role":"Responsable du risque","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le niveau découle-t-il de la matrice de la méthode ?","Le niveau résiduel est-il distingué de l'inhérent ?"],"expected_evidence":["Registre des risques : niveaux inhérent et résiduel","Matrice de la méthode"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-006","version":"0.3","title":"Appétence et tolérance au risque","status":"draft","control_type":"baseline","objective":"La direction fixe le niveau de risque acceptable pour l'IA et les seuils au-delà desquels un risque exige un traitement, une acceptation formelle ou un refus. Les gates s'y réfèrent.","owner_role":"Direction","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["L'appétence au risque IA est-elle écrite et approuvée par la direction ?","Les seuils sont-ils appliqués par les gates et les acceptations ?"],"expected_evidence":["Déclaration d'appétence au risque","Règles des gates y faisant référence"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.2.2"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-007","version":"0.3","title":"Plan de traitement","status":"draft","control_type":"baseline","objective":"Chaque risque au-dessus du seuil a un traitement décidé — réduire, transférer, éviter, accepter — porté par un contrôle nommé, un responsable et une échéance. Un traitement sans contrôle est une intention.","owner_role":"Responsable du risque","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Chaque risque élevé a-t-il un traitement rattaché à un contrôle ?","Les traitements ont-ils un responsable et une échéance ?"],"expected_evidence":["Registre des risques : traitements et contrôles rattachés","Actions de traitement suivies"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"},{"framework":"AI_ACT","reference":"Art. 9 (mesures de gestion des risques)"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-008","version":"0.3","title":"Évaluation du risque résiduel","status":"draft","control_type":"baseline","objective":"Une fois le traitement en place et son efficacité constatée, le risque résiduel est recoté ; c'est lui, et non le risque inhérent, que la direction accepte ou refuse.","owner_role":"Responsable du risque","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le résiduel est-il recoté après mise en œuvre du traitement, sur constat et non sur intention ?"],"expected_evidence":["Registre des risques : niveau résiduel daté","Preuve d'efficacité du contrôle"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-009","version":"0.3","title":"Acceptation formelle du risque","status":"draft","control_type":"baseline","objective":"Un risque résiduel au-dessus du seuil n'est accepté que par une décision nominative d'un rôle habilité, avec justification, date de revue, et sans que l'auteur de la demande soit l'approbateur.","owner_role":"Responsable du risque","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les acceptations portent-elles un approbateur nommé, une justification et une date de revue ?","La séparation demandeur / approbateur est-elle respectée ?"],"expected_evidence":["Registre de décisions : acceptations de risque","Registre des risques : statut accepté avec revue"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.3.2"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-010","version":"0.3","title":"Revue périodique des risques","status":"draft","control_type":"baseline","objective":"Les risques sont revus à la cadence de la méthode et à chaque changement significatif ; les acceptations arrivées à échéance sont renouvelées ou retirées explicitement.","owner_role":"Responsable du risque","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les revues ont-elles lieu à la cadence prévue ?","Aucune acceptation n'est-elle échue sans décision ?"],"expected_evidence":["Registre des risques : dates de revue","Compte rendu de revue des risques"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"9.3"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-011","version":"0.3","title":"Risques émergents","status":"draft","control_type":"baseline","objective":"L'organisation surveille les risques nouveaux — évolutions réglementaires, vulnérabilités des modèles, incidents dans le secteur, nouveaux usages — et les intègre à son registre sans attendre la revue périodique.","owner_role":"AI Governance Officer","review_frequency":"quarterly","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Une veille est-elle organisée, avec un responsable et des sources ?","Ses résultats alimentent-ils le registre des risques ?"],"expected_evidence":["Procédure de veille","Risques ajoutés hors revue périodique, avec leur source"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.8.4"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-RSK-012","version":"0.3","title":"Évaluation d'impact des systèmes d'IA","status":"draft","control_type":"baseline","objective":"Une évaluation d'impact est conduite pour chaque cas d'usage selon ISO/IEC 42005 : parties affectées, bénéfices, préjudices potentiels, mesures d'atténuation, conclusion. Elle est approuvée et rouverte à chaque changement significatif.","owner_role":"AI Governance Officer","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Une évaluation d'impact approuvée existe-t-elle pour chaque usage en service ?","Couvre-t-elle les personnes affectées, y compris vulnérables, et les impacts sociétaux ?"],"expected_evidence":["Évaluation d'impact approuvée et datée","Constats et mesures d'atténuation suivis"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"8.4"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.5"},{"framework":"AI_ACT","reference":"Art. 27 (analyse d'impact sur les droits fondamentaux)"}],"remediation_guidance":[],"domain":"RSK"},{"code":"AIGMS-DAT-001","version":"0.3","title":"Inventaire des données mobilisées par l'IA","status":"draft","control_type":"baseline","objective":"Chaque jeu de données que l'IA consomme, produit ou apprend — entraînement, réglage, évaluation, exploitation, journaux — est inscrit, avec sa source, son propriétaire et le système qui l'utilise.","owner_role":"Responsable des données","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Chaque système en service a-t-il ses jeux de données inscrits ?","L'inventaire distingue-t-il entraînement, exploitation et journaux ?"],"expected_evidence":["Registre des actifs : jeux de données rattachés aux systèmes","Fiche de chaque jeu : source, propriétaire, usage"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.2"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-002","version":"0.3","title":"Propriétaire des données","status":"draft","control_type":"baseline","objective":"Chaque jeu de données a un propriétaire nommé qui répond de sa qualité, de sa base légale, de sa conservation et de son usage par l'IA — et qui est consulté avant tout nouvel usage.","owner_role":"Responsable des données","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Aucun jeu de données n'est-il sans propriétaire ?","Le propriétaire a-t-il validé l'usage par l'IA ?"],"expected_evidence":["Inventaire : colonne propriétaire renseignée","Trace de validation d'usage"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.3.2"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-003","version":"0.3","title":"Classification des données","status":"draft","control_type":"baseline","objective":"Les données mobilisées par l'IA portent une classification (publique, interne, confidentielle, restreinte) qui commande ce qu'on peut leur faire : soumettre à un modèle tiers, journaliser, conserver, partager.","owner_role":"Responsable des données","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Chaque jeu de données porte-t-il sa classification ?","La politique d'usage acceptable s'y réfère-t-elle ?"],"expected_evidence":["Grille de classification","Inventaire classifié","Règles d'usage par niveau"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-004","version":"0.3","title":"Données à caractère personnel","status":"draft","control_type":"baseline","objective":"Quand l'IA traite des données personnelles, la base légale, la finalité, l'information des personnes et leurs droits sont assurés, et le traitement figure au registre RGPD ; l'analyse d'impact (AIPD) est conduite quand elle est requise.","owner_role":"DPO","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Le traitement figure-t-il au registre RGPD avec sa base légale ?","Une AIPD a-t-elle été conduite si le traitement le requiert ?","Les personnes sont-elles informées de l'usage de l'IA ?"],"expected_evidence":["Extrait du registre des traitements","AIPD","Mention d'information"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.4"},{"framework":"AI_ACT","reference":"Art. 10 (données et gouvernance des données)"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-005","version":"0.3","title":"Données sensibles","status":"draft","control_type":"baseline","objective":"Les catégories particulières de données — origine, opinions, santé, orientation, biométrie — ne sont mobilisées par l'IA qu'avec une base légale spécifique, une justification écrite et des mesures renforcées, et jamais soumises à un modèle tiers sans garanties contractuelles.","owner_role":"DPO","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["L'usage de données sensibles est-il identifié et justifié ?","Est-il exclu des modèles tiers sans garanties ?"],"expected_evidence":["Justification et base légale","Mesures renforcées documentées","Clauses contractuelles du fournisseur"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.4"},{"framework":"AI_ACT","reference":"Art. 10 §5 (catégories particulières)"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-006","version":"0.3","title":"Données de santé","status":"draft","control_type":"baseline","objective":"Quand l'IA traite des données de santé, l'hébergement, l'accès, le secret et la traçabilité respectent les exigences propres à ces données (hébergement certifié, habilitations, journalisation des accès), et le professionnel de santé reste décideur.","owner_role":"DPO","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["L'hébergement est-il conforme aux exigences applicables aux données de santé ?","Les accès sont-ils habilités et journalisés ?"],"expected_evidence":["Attestation d'hébergement certifié","Matrice d'habilitation","Journal des accès"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.5.4"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-007","version":"0.3","title":"Provenance et traçabilité des données","status":"draft","control_type":"baseline","objective":"On sait d'où vient chaque jeu de données, par quelles transformations il est passé et quelle version a servi à quel modèle. Sans provenance, ni un biais ni une fuite ne se remontent.","owner_role":"Responsable des données","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La provenance de chaque jeu est-elle documentée ?","Les transformations et versions sont-elles tracées jusqu'au modèle ?"],"expected_evidence":["Fiche de provenance (lineage)","Journal des transformations","Correspondance version de données / version de modèle"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.5"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.6"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-008","version":"0.3","title":"Qualité des données","status":"draft","control_type":"baseline","objective":"Les données d'entraînement et d'exploitation sont évaluées sur des critères définis — exactitude, complétude, représentativité, actualité — avant usage et périodiquement ; les écarts sont traités ou assumés.","owner_role":"Responsable des données","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Des critères de qualité sont-ils définis et mesurés ?","La représentativité par rapport aux personnes concernées est-elle vérifiée ?"],"expected_evidence":["Rapport de qualité des données","Critères et seuils","Traitement des écarts"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.4"},{"framework":"AI_ACT","reference":"Art. 10 §3 (pertinence, représentativité)"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-009","version":"0.3","title":"Minimisation des données","status":"draft","control_type":"baseline","objective":"L'IA ne reçoit que les données nécessaires à sa finalité : les champs superflus sont retirés, les identifiants pseudonymisés quand c'est possible, et ce choix est justifié pour chaque flux.","owner_role":"DPO","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les données transmises au modèle sont-elles limitées au nécessaire ?","La pseudonymisation a-t-elle été envisagée et, sinon, l'écart justifié ?"],"expected_evidence":["Cartographie des flux vers le modèle","Justification de chaque champ transmis"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.6"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-010","version":"0.3","title":"Conservation et suppression","status":"draft","control_type":"baseline","objective":"Chaque catégorie de données mobilisée par l'IA — entrées, sorties, journaux, données d'entraînement — a une durée de conservation définie, appliquée et vérifiable, y compris chez le fournisseur.","owner_role":"Responsable des données","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les durées de conservation sont-elles définies par catégorie, journaux compris ?","Leur application est-elle vérifiée, chez le fournisseur aussi ?"],"expected_evidence":["Politique de conservation","Preuve de purge","Engagement contractuel du fournisseur"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-011","version":"0.3","title":"Transferts et localisation des données","status":"draft","control_type":"baseline","objective":"On sait où les données mobilisées par l'IA sont traitées et stockées — pays, hébergeur, sous-traitants — et tout transfert hors du cadre applicable repose sur un instrument valide.","owner_role":"DPO","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La localisation des traitements est-elle connue pour chaque système ?","Les transferts sont-ils couverts par un instrument juridique valide ?"],"expected_evidence":["Cartographie des localisations","Clauses de transfert","Liste des sous-traitants et de leurs pays"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-DAT-012","version":"0.3","title":"Données d'entraînement et de réglage","status":"draft","control_type":"baseline","objective":"Les données utilisées pour entraîner ou régler un modèle sont sélectionnées, documentées et conservées avec le modèle : composition, licence, biais connus, exclusions. Un modèle dont on ne sait pas de quoi il a appris ne se défend pas.","owner_role":"Responsable des données","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["La composition des données d'entraînement est-elle documentée avec le modèle ?","Les licences et droits d'usage sont-ils vérifiés ?","Les biais connus sont-ils décrits ?"],"expected_evidence":["Fiche de données d'entraînement (datasheet)","Vérification des licences","Analyse de représentativité"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.4"},{"framework":"AI_ACT","reference":"Art. 10 (jeux d'entraînement, validation, test)"}],"remediation_guidance":[],"domain":"DAT"},{"code":"AIGMS-SEC-001","version":"0.3","title":"Sécurité dès la conception des systèmes d'IA","status":"draft","control_type":"baseline","objective":"Les risques de sécurité propres à l'IA — injection, exfiltration, empoisonnement, abus d'API, fuite par les sorties — sont analysés à la conception de chaque système, et les mesures retenues sont décidées avant la mise en service, en articulation avec le SMSI.","owner_role":"RSSI","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Une analyse de menaces spécifique à l'IA a-t-elle été conduite avant la mise en service ?","Les mesures retenues sont-elles tracées dans le dispositif de contrôles ?"],"expected_evidence":["Analyse de menaces IA","Décisions de sécurité consignées","Articulation avec le SMSI (ISO 27001)"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.1.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.2"},{"framework":"AI_ACT","reference":"Art. 15 (exactitude, robustesse, cybersécurité)"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-002","version":"0.3","title":"Identités et accès aux systèmes d'IA","status":"draft","control_type":"baseline","objective":"L'accès aux systèmes d'IA, à leurs consoles, API, données et journaux passe par des identités nominatives, authentifiées de façon forte, attribuées et retirées selon un processus tracé.","owner_role":"RSSI","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les accès sont-ils nominatifs, avec authentification forte ?","Les attributions et retraits sont-ils tracés et revus ?"],"expected_evidence":["Matrice d'habilitation","Revue périodique des accès","Configuration de l'authentification"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.5"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-003","version":"0.3","title":"Moindre privilège","status":"draft","control_type":"baseline","objective":"Un système d'IA — et en particulier un agent — ne dispose que des droits strictement nécessaires à sa finalité, sur les données comme sur les actions ; les droits d'écriture et d'exécution sont accordés explicitement et revus.","owner_role":"RSSI","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les droits du système sont-ils limités à sa finalité ?","Un agent qui agit a-t-il des droits d'exécution bornés et revus ?"],"expected_evidence":["Inventaire des droits par système","Revue des privilèges","Périmètre d'action de l'agent documenté"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-004","version":"0.3","title":"Gestion des secrets","status":"draft","control_type":"baseline","objective":"Clés d'API, jetons et identifiants des systèmes d'IA sont stockés dans un coffre, jamais dans le code, les prompts ou les journaux ; ils sont renouvelés à cadence fixe et révoqués sans délai en cas de doute.","owner_role":"RSSI","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les secrets vivent-ils dans un coffre, hors du code et des prompts ?","La rotation et la révocation sont-elles organisées ?"],"expected_evidence":["Inventaire des secrets et leur emplacement","Journal de rotation","Détection de secrets dans le code"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.5"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-005","version":"0.3","title":"Chiffrement","status":"draft","control_type":"baseline","objective":"Les données mobilisées par l'IA sont chiffrées en transit et au repos — entrées, sorties, journaux, données d'entraînement, index vectoriels compris — avec des clés gérées et, quand la classification l'exige, détenues par l'organisation.","owner_role":"RSSI","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le chiffrement couvre-t-il les index et journaux, pas seulement les bases ?","La gestion des clés est-elle documentée ?"],"expected_evidence":["Configuration de chiffrement","Politique de gestion des clés","Attestation du fournisseur"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.5"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-006","version":"0.3","title":"Journalisation de sécurité des systèmes d'IA","status":"draft","control_type":"baseline","objective":"Les accès, requêtes, réponses, actions d'agent et changements de configuration des systèmes d'IA sont journalisés, horodatés, protégés en intégrité et conservés assez longtemps pour reconstituer un incident — sans y consigner de secrets ni plus de données personnelles que nécessaire.","owner_role":"RSSI","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les journaux permettent-ils de reconstituer qui a demandé quoi, et ce que le système a fait ?","Sont-ils protégés en intégrité et conservés selon la politique ?"],"expected_evidence":["Spécification de journalisation","Extrait de journal","Configuration de conservation et d'intégrité"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.8"},{"framework":"AI_ACT","reference":"Art. 12 (enregistrement automatique)"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-007","version":"0.3","title":"Protection contre les injections de requêtes","status":"draft","control_type":"baseline","objective":"Les systèmes fondés sur des modèles de langage sont protégés contre les instructions malveillantes injectées par l'utilisateur ou par les contenus qu'ils lisent — documents, pages, courriels : séparation des instructions et des données, filtrage, limitation des actions déclenchables, tests réguliers.","owner_role":"RSSI","review_frequency":"quarterly","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Les contenus lus par le modèle sont-ils traités comme non fiables ?","Les actions qu'une injection pourrait déclencher sont-elles bornées ?","Des tests d'injection sont-ils rejoués à chaque changement ?"],"expected_evidence":["Architecture de séparation instructions / données","Résultats de tests d'injection","Liste des actions déclenchables et leurs garde-fous"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.4"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"},{"framework":"AI_ACT","reference":"Art. 15 (robustesse, cybersécurité)"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-008","version":"0.3","title":"Prévention de l'exfiltration de données","status":"draft","control_type":"baseline","objective":"Un système d'IA ne peut pas servir de canal de sortie pour des données qu'il ne devrait pas divulguer : contrôle des données soumises aux modèles tiers, filtrage des sorties, blocage des liens et appels sortants non prévus, détection des fuites par les prompts.","owner_role":"RSSI","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les données soumises aux modèles tiers sont-elles contrôlées selon leur classification ?","Les sorties et appels sortants du système sont-ils filtrés ?"],"expected_evidence":["Règles de filtrage entrée/sortie","Configuration des appels sortants autorisés","Rapport de détection"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-009","version":"0.3","title":"Protection contre l'abus des modèles et des API","status":"draft","control_type":"baseline","objective":"Les modèles et leurs API sont protégés contre l'usage abusif : quotas, limitation de débit, détection des motifs d'extraction ou de contournement, surveillance des coûts, révocation des clés compromises.","owner_role":"RSSI","review_frequency":"quarterly","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Des quotas et limites de débit sont-ils en place par client ou par clé ?","Les motifs d'abus sont-ils détectés et alertés ?"],"expected_evidence":["Configuration des quotas","Alertes d'abus et leur traitement","Suivi des coûts par système"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.5"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-010","version":"0.3","title":"Validation des entrées","status":"draft","control_type":"baseline","objective":"Ce qui entre dans un système d'IA — requêtes, fichiers, données d'intégration — est validé : format, taille, type, provenance, absence de contenu interdit. Une entrée non validée est une surface d'attaque.","owner_role":"Porteur du système","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les entrées sont-elles validées avant d'atteindre le modèle ?","Les fichiers reçus sont-ils analysés ?"],"expected_evidence":["Règles de validation","Tests de validation","Journal des rejets"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.4"},{"framework":"AI_ACT","reference":"Art. 15 (robustesse)"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-011","version":"0.3","title":"Validation des sorties","status":"draft","control_type":"baseline","objective":"Ce qu'un système d'IA produit est vérifié avant d'être remis ou exécuté : format attendu, absence de données à ne pas divulguer, de contenu interdit, d'instructions dangereuses ; une sortie qui déclenche une action passe par un contrôle supplémentaire.","owner_role":"Porteur du système","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les sorties sont-elles vérifiées avant remise ou exécution ?","Une sortie qui déclenche une action passe-t-elle un contrôle spécifique ?"],"expected_evidence":["Règles de validation des sorties","Garde-fous sur les actions","Journal des sorties bloquées"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.4"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SEC-012","version":"0.3","title":"Tests de sécurité des systèmes d'IA","status":"draft","control_type":"baseline","objective":"Chaque système d'IA est soumis à des tests de sécurité spécifiques avant mise en service et à chaque changement significatif — injection, extraction, contournement, abus — conduits ou revus par une équipe indépendante du développement, avec des constats suivis jusqu'à correction.","owner_role":"RSSI","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Des tests de sécurité IA (red teaming) ont-ils été conduits avant la mise en service ?","Les constats ont-ils été corrigés et re-testés ?"],"expected_evidence":["Rapport de tests de sécurité","Suivi des constats","Preuve de re-test"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.4"},{"framework":"AI_ACT","reference":"Art. 15 (cybersécurité) ; Art. 55 (modèles à usage général, tests contradictoires)"}],"remediation_guidance":[],"domain":"SEC"},{"code":"AIGMS-SUP-001","version":"0.3","title":"Inventaire des fournisseurs d'IA","status":"draft","control_type":"baseline","objective":"Tout tiers qui fournit un modèle, une plateforme, une API ou un service d'IA à l'organisation est inscrit, rattaché aux systèmes qu'il sert, avec sa criticité et l'état de sa revue.","owner_role":"AI Governance Officer","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Chaque système en service a-t-il ses fournisseurs inscrits ?","Les fournisseurs de modèle sont-ils distingués des intégrateurs ?"],"expected_evidence":["Registre des fournisseurs rattachés aux cas d'usage","Criticité et statut de revue par fournisseur"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.2"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-002","version":"0.3","title":"Revue préalable du fournisseur","status":"draft","control_type":"baseline","objective":"Avant d'utiliser un fournisseur d'IA, une revue proportionnée à sa criticité examine sa sécurité, sa conformité, l'usage qu'il fait des données, sa localisation, sa pérennité et ses conditions ; son résultat est consigné et conditionne la mise en service.","owner_role":"AI Governance Officer","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Chaque fournisseur impliqué dans un usage en service a-t-il une revue close ?","La revue est-elle proportionnée à la criticité et renouvelée ?"],"expected_evidence":["Questionnaire ou rapport de revue","Décision de revue consignée","Date de prochaine revue"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.2"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-003","version":"0.3","title":"Localisation des données chez le fournisseur","status":"draft","control_type":"baseline","objective":"L'organisation sait dans quels pays le fournisseur traite et stocke ses données — y compris pour l'entraînement, le support et les sauvegardes — et cette localisation est compatible avec ses obligations.","owner_role":"DPO","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La localisation est-elle contractuellement fixée ?","Couvre-t-elle le support et les sauvegardes ?"],"expected_evidence":["Clause de localisation","Documentation du fournisseur","Liste des régions utilisées"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-004","version":"0.3","title":"Conditions contractuelles d'utilisation","status":"draft","control_type":"baseline","objective":"Les conditions d'utilisation de chaque fournisseur d'IA sont lues, comprises et acceptées en connaissance de cause : usages permis, propriété des sorties, responsabilité, changements unilatéraux ; une version de référence est conservée.","owner_role":"AI Governance Officer","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les conditions ont-elles été analysées et la version acceptée conservée ?","Les changements de conditions sont-ils surveillés ?"],"expected_evidence":["Analyse des conditions","Version conservée et datée","Veille sur les changements"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-005","version":"0.3","title":"Utilisation des données par le fournisseur","status":"draft","control_type":"baseline","objective":"Il est établi contractuellement si le fournisseur peut utiliser les données soumises pour entraîner ses modèles, les conserver, les relire ; le choix de l'organisation est exercé (refus d'entraînement, options de rétention) et vérifié.","owner_role":"DPO","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["L'usage des données par le fournisseur est-il contractuellement borné ?","Les options de refus ont-elles été exercées et vérifiées ?"],"expected_evidence":["Clause d'usage des données","Capture de la configuration (refus d'entraînement)","Accord de traitement (DPA)"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.7.3"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-006","version":"0.3","title":"Engagements de service","status":"draft","control_type":"baseline","objective":"Pour un fournisseur critique, les engagements de disponibilité, de performance, de support et de notification (incidents, changements de modèle, dépréciations) sont contractualisés et suivis.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Les engagements de service sont-ils écrits et mesurés ?","Le fournisseur notifie-t-il les changements de modèle et les incidents ?"],"expected_evidence":["SLA contractuel","Suivi des indicateurs","Notifications reçues"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-007","version":"0.3","title":"Assurance de sécurité du fournisseur","status":"draft","control_type":"baseline","objective":"La sécurité du fournisseur est établie par des éléments vérifiables — certification, rapport d'audit indépendant, questionnaire renseigné, résultats de tests — proportionnés à la criticité, et renouvelés.","owner_role":"RSSI","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le fournisseur produit-il une assurance de sécurité vérifiable ?","Est-elle à jour et couvre-t-elle le service réellement utilisé ?"],"expected_evidence":["Certificat (ISO 27001, SOC 2…)","Rapport d'audit","Questionnaire de sécurité"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-008","version":"0.3","title":"Sous-traitants du fournisseur","status":"draft","control_type":"baseline","objective":"Les sous-traitants auxquels le fournisseur d'IA recourt — hébergeur, fournisseur de modèle sous-jacent, support — sont connus, avec leur localisation, et leur changement est notifié.","owner_role":"DPO","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La chaîne de sous-traitance est-elle connue jusqu'au modèle sous-jacent ?","Les changements sont-ils notifiés et évalués ?"],"expected_evidence":["Liste des sous-traitants","Clause de notification","Évaluation d'un changement"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.2"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-009","version":"0.3","title":"Risque de dépendance au fournisseur","status":"draft","control_type":"baseline","objective":"La dépendance à chaque fournisseur d'IA est évaluée — substituabilité du modèle, portabilité des données et des prompts, coût de sortie — et, quand elle est forte, traitée : alternative identifiée, abstraction technique, acceptation formelle.","owner_role":"Responsable du risque","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["La dépendance est-elle évaluée et inscrite au registre des risques ?","Une alternative est-elle identifiée pour les fournisseurs critiques ?"],"expected_evidence":["Risque de dépendance au registre","Analyse de substituabilité","Décision de traitement ou d'acceptation"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"6.1.2"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-SUP-010","version":"0.3","title":"Réversibilité et stratégie de sortie","status":"draft","control_type":"baseline","objective":"Pour chaque fournisseur critique, l'organisation sait comment sortir : récupération des données, des configurations, des prompts et des index ; suppression chez le fournisseur ; délai et coût ; la procédure est documentée et testée.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["La procédure de sortie est-elle documentée, données et configurations comprises ?","A-t-elle été testée au moins partiellement ?"],"expected_evidence":["Plan de réversibilité","Clause de restitution et de suppression","Compte rendu de test"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.10.3"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"}],"remediation_guidance":[],"domain":"SUP"},{"code":"AIGMS-HUM-001","version":"0.3","title":"Niveau de supervision humaine","status":"draft","control_type":"baseline","objective":"Pour chaque système, le niveau de supervision humaine est décidé en fonction de son autonomie et de son impact — humain dans la boucle, sur la boucle, hors boucle — et documenté dans un plan de supervision qui nomme qui surveille, quoi, et comment.","owner_role":"AI Governance Officer","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Un plan de supervision existe-t-il pour chaque usage en service ?","Le niveau retenu est-il cohérent avec l'autonomie et l'impact ?"],"expected_evidence":["Plan de supervision humaine approuvé","Cohérence avec le niveau d'autonomie et la criticité"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.6.2.6"},{"framework":"AI_ACT","reference":"Art. 14 (contrôle humain)"}],"remediation_guidance":[],"domain":"HUM"},{"code":"AIGMS-HUM-002","version":"0.3","title":"Validation humaine des décisions","status":"draft","control_type":"baseline","objective":"Une décision produite ou proposée par l'IA qui a un effet significatif sur une personne est validée par un humain compétent avant de produire son effet — et cette validation est réelle : le validateur a le temps, l'information et le pouvoir de refuser.","owner_role":"Porteur du système","review_frequency":"semiannual","applicability":{"default":"conditional"},"risks":[],"requirements":[],"assessment_questions":["Les décisions à effet significatif passent-elles par une validation humaine effective ?","Le taux de refus par les validateurs est-il suivi (une validation qui n'en refuse jamais n'en est pas une) ?"],"expected_evidence":["Procédure de validation","Journal des validations et refus","Indicateur de taux de refus"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"},{"framework":"AI_ACT","reference":"Art. 14 (contrôle humain) ; RGPD Art. 22"}],"remediation_guidance":[],"domain":"HUM"},{"code":"AIGMS-HUM-003","version":"0.3","title":"Compétence du validateur","status":"draft","control_type":"baseline","objective":"Les personnes qui supervisent ou valident les sorties d'un système d'IA connaissent ses capacités, ses limites, ses biais connus et les signes de défaillance ; elles sont désignées, formées, et leur compétence est entretenue.","owner_role":"Porteur du système","review_frequency":"annual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Les validateurs sont-ils désignés et formés aux limites du système ?","La formation est-elle renouvelée à chaque changement significatif ?"],"expected_evidence":["Liste des validateurs","Support et attestations de formation","Fiche des limites connues du système"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.4.6"},{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"},{"framework":"AI_ACT","reference":"Art. 14 §4 ; Art. 4"}],"remediation_guidance":[],"domain":"HUM"},{"code":"AIGMS-HUM-004","version":"0.3","title":"Reprise de la main","status":"draft","control_type":"baseline","objective":"Un humain habilité peut, à tout moment, écarter une sortie, corriger une décision ou reprendre la main sur un système d'IA — et le faire sans délai ni obstacle technique ; les reprises de main sont journalisées et analysées.","owner_role":"Porteur du système","review_frequency":"semiannual","applicability":{"default":"mandatory"},"risks":[],"requirements":[],"assessment_questions":["Le mécanisme de reprise de main existe-t-il et est-il accessible sans délai ?","Les reprises sont-elles journalisées et analysées ?"],"expected_evidence":["Procédure de reprise de main","Journal des reprises","Analyse des motifs"],"tests":[],"maturity_model":{"0":"Absent","1":"Documenté","2":"Implémenté","3":"Mesuré","4":"Automatisé / Amélioré"},"framework_mappings":[{"framework":"ISO_IEC_42001","version":"2023","reference":"A.9.2"},{"framework":"AI_ACT","reference"