    assessment_questions jsonb, expected_evidence jsonb, tests jsonb, maturity_model jsonb,
    framework_mappings jsonb, remediation_guidance jsonb, domain text
  )
  join public.catalog_domain d on d.version_id = v_version and d.code = c.domain;

  insert into public.catalog_profile (version_id, profile_code, name, description)
  select v_version, p ->> 'id', p ->> 'name', p ->> 'description'
  from jsonb_array_elements($profiles$[{"id":"AIGMS-PROFILE-01","name":"Employee GenAI","description":"Assistants IA généralistes pour collaborateurs."},{"id":"AIGMS-PROFILE-02","name":"Internal RAG","description":"RAG interne sur procédures, KB et documentation."},{"id":"AIGMS-PROFILE-03","name":"Customer Chatbot","description":"Chatbot ou assistant conversationnel exposé aux clients."},{"id":"AIGMS-PROFILE-04","name":"AI Assisted Operations","description":"IA d'assistance aux opérations NOC / exploitation."},{"id":"AIGMS-PROFILE-05","name":"AI Security Operations","description":"IA d'assistance SOC / cybersécurité."},{"id":"AIGMS-PROFILE-06","name":"Autonomous Agent","description":"Agent capable d'exécuter des actions sur le SI."},{"id":"AIGMS-PROFILE-07","name":"AI SaaS Provider","description":"Service IA fourni en mode SaaS."},{"id":"AIGMS-PROFILE-08","name":"AI Infrastructure Provider","description":"Hébergement, GPU, LLM gateway ou infrastructure IA."},{"id":"AIGMS-PROFILE-09","name":"Sensitive Data AI","description":"IA traitant des données sensibles ou critiques."},{"id":"AIGMS-PROFILE-10","name":"Healthcare AI","description":"IA impliquant des données ou usages liés à la santé."}]$profiles$::jsonb) p;

  insert into public.catalog_reference_use_case (version_id, use_case_code, name, example)
  select v_version, u ->> 'id', u ->> 'name', u ->> 'example'
  from jsonb_array_elements($usecases$[{"id":"UC01","name":"Copilot bureautique","example":"Microsoft 365 Copilot / ChatGPT Enterprise / Claude Enterprise pour collaborateurs"},{"id":"UC02","name":"IA support client","example":"Assistant de réponse aux tickets"},{"id":"UC03","name":"RAG documentation","example":"Interrogation de procédures, KB, contrats et documentation"},{"id":"UC04","name":"IA NOC","example":"Analyse d'alarmes réseau et datacenter"},{"id":"UC05","name":"IA SOC","example":"Analyse d'événements cybersécurité"},{"id":"UC06","name":"Incident summarization","example":"Résumé automatique d'incidents"},{"id":"UC07","name":"Root Cause Analysis","example":"Proposition de causes probables d'incidents"},{"id":"UC08","name":"Capacity Planning","example":"Prévision CPU, RAM, stockage et bande passante"},{"id":"UC09","name":"Predictive Maintenance","example":"Anticipation de pannes d'équipements"},{"id":"UC10","name":"Ticket classification","example":"Classification et routage des tickets"},{"id":"UC11","name":"Customer chatbot","example":"Chatbot client cloud / télécom"},{"id":"UC12","name":"Contract assistant","example":"Analyse de SLA, contrats et DPA"},{"id":"UC13","name":"Sales assistant","example":"Génération de propositions commerciales"},{"id":"UC14","name":"Customer AI hosting","example":"Hébergement de workloads IA clients"},{"id":"UC15","name":"GPU-as-a-Service","example":"Infrastructure GPU locale"},{"id":"UC16","name":"Managed RAG","example":"RAG opéré pour le compte d'un client"},{"id":"UC17","name":"Managed AI agent","example":"Agent IA opéré en service managé"},{"id":"UC18","name":"HDS + AI","example":"Traitement IA de données liées à la santé"}]$usecases$::jsonb) u;

  -- Publication : une seule version publiée par référentiel, la précédente
  -- passe « remplacée ».
  update public.catalog_version set status = 'superseded'
   where framework_id = v_framework and id <> v_version and status = 'published';
  update public.catalog_version set status = 'published', published_at = now()
   where id = v_version;
end $$;
